const topicLabels={"typography": "Typography", "photography": "Photography", "fashion": "Fashion", "architecture": "Architecture", "graphic-design": "Graphic Design"},topicSources={"typography": ["https://www.itsnicethat.com/", "https://www.behance.net/", "https://www.designspiration.com/", "https://www.printedmatter.org/"], "photography": ["https://www.nowness.com/", "https://www.showstudio.com/", "https://www.ignant.com/", "https://www.booooooom.com/", "https://www.dazeddigital.com/fashion"], "architecture": ["https://www.apartamentomagazine.com/", "https://www.ignant.com/", "https://www.thisiscolossal.com/", "https://www.itsnicethat.com/", "https://www.behance.net/"], "graphic-design": ["https://www.itsnicethat.com/", "https://www.behance.net/", "https://www.designspiration.com/", "https://magazine-b.com/", "https://www.printedmatter.org/"]};let topic='';
function matchesTopic(card: HTMLElement){return !topic||(topic==='fashion'?card.dataset.category==='Fashion references':topicSources[topic]?.includes(card.querySelector<HTMLButtonElement>('.favorite-source').dataset.url));}
function refreshTopics(){document.querySelectorAll<HTMLButtonElement>('[data-topic]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.topic===topic)));}
let activeLocale='en';function t(value){return translations[activeLocale]?.[value]||value;}const cards=[...document.querySelectorAll<HTMLElement>('.source')];const tickerCount=document.querySelector<HTMLSpanElement>('[data-source-count]');if(tickerCount){const nextCount=tickerCount.textContent.replace(/^\d+/,String(cards.length));if(nextCount!==tickerCount.textContent)tickerCount.textContent=nextCount;}let category='All';const search=document.querySelector<HTMLInputElement>('#search'),region=document.querySelector<HTMLSelectElement>('#region'),accessFilter=document.querySelector<HTMLSelectElement>('#access-filter'),countryFilter=document.querySelector<HTMLSelectElement>('#country-filter'),buttons=[...document.querySelectorAll<HTMLButtonElement>('[data-filter]')];const accessByCard=new Map(cards.map(c=>[c,c.querySelector<HTMLElement>('.comparison div:last-child dd').textContent.trim()]));function activeFilterCount(){return (category==='All'?0:1)+(region.value==='All'?0:1)+(accessFilter.value==='All'?0:1)+(countryFilter.value==='All'?0:1)+(search.value.trim()?1:0)+(favoritesOnly?1:0)+(topic?1:0);}function update(){refreshTopics();syncFilterBadge();document.querySelector<HTMLSelectElement>('#category-filter').value=category;document.querySelector<HTMLButtonElement>('#reset').disabled=activeFilterCount()===0;[countryFilter,region,accessFilter].forEach(el=>el.classList.toggle('is-active',el.value!=='All'));document.querySelector<HTMLSelectElement>('#category-filter').classList.toggle('is-active',category!=='All');let n=0;const q=search.value.trim().toLocaleLowerCase();const matches=(c: HTMLElement)=>matchesTopic(c)&&(!favoritesOnly||favoriteKeys.has(c.querySelector<HTMLButtonElement>('.favorite-source').dataset.url))&&(region.value==='All'||c.dataset.region===region.value)&&(accessFilter.value==='All'||accessByCard.get(c)===accessFilter.value)&&(countryFilter.value==='All'||c.dataset.country===countryFilter.value)&&c.textContent.toLocaleLowerCase().includes(q);cards.forEach(c=>{const show=(category==='All'||c.dataset.category===category)&&matches(c);c.hidden=!show;if(show)n++;});buttons.forEach(b=>{const total=cards.filter(c=>matches(c)&&(b.dataset.filter==='All'||c.dataset.category===b.dataset.filter)).length;b.querySelector<HTMLSpanElement>('.filter-count').textContent=String(total);b.setAttribute('aria-pressed',String(b.dataset.filter===category));b.setAttribute('aria-label',(b.dataset.filter==='All'?'All sources':b.dataset.filter)+': '+total+' sources');});document.querySelector<HTMLParagraphElement>('#count').textContent=n+' of '+cards.length+' sources';document.querySelector<HTMLParagraphElement>('#empty').hidden=n!==0;document.querySelector<HTMLButtonElement>('#clear-filters').hidden=n!==0;const active=activeFilterCount();document.querySelector<HTMLSpanElement>('#active-filters').textContent=active?active+' active':'All sources';syncViewURL();refreshDynamicLabels();refreshFavorites();}document.querySelectorAll<HTMLButtonElement>('[data-topic]').forEach(button=>button.addEventListener('click',()=>{topic=button.dataset.topic;update();}));buttons.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;update();}));search.addEventListener('input',update);document.querySelector<HTMLSelectElement>('#category-filter').addEventListener('change',e=>{category=(e.target as HTMLSelectElement).value;update();});region.addEventListener('change',update);accessFilter.addEventListener('change',update);countryFilter.addEventListener('change',update);document.querySelector<HTMLButtonElement>('#reset').addEventListener('click',()=>{category='All';topic='';search.value='';region.value='All';accessFilter.value='All';countryFilter.value='All';favoritesOnly=false;update();search.focus({preventScroll:true});});function expandPrint(){document.querySelectorAll<HTMLDetailsElement>('.research-route,.guide-record,.source-details').forEach(d=>{d.dataset.printOpen=String(d.open);d.open=true;});}function restorePrint(){document.querySelectorAll<HTMLDetailsElement>('.research-route,.guide-record,.source-details').forEach(d=>{if(d.dataset.printOpen!==undefined){d.open=d.dataset.printOpen==='true';delete d.dataset.printOpen;}});}window.addEventListener('beforeprint',expandPrint);window.addEventListener('afterprint',restorePrint);const panel=document.querySelector<HTMLDetailsElement>('.filter-panel'),phone=matchMedia('(max-width:639px)');let mobileOpen=false;function adaptFilters(){panel.open=phone.matches?mobileOpen:true;document.querySelector<HTMLButtonElement>('#filter-toggle').setAttribute('aria-expanded',String(panel.open));}panel.addEventListener('toggle',()=>{if(phone.matches)mobileOpen=panel.open;document.querySelector<HTMLButtonElement>('#filter-toggle').setAttribute('aria-expanded',String(panel.open));});if(phone.addEventListener)phone.addEventListener('change',adaptFilters);else phone.addListener(adaptFilters);adaptFilters();
