let paletteMatches=[],paletteIndex=0;
function paletteItems(){return cards.map((card,index)=>{const link=card.querySelector<HTMLAnchorElement>('h3 a');return {card,index,title:link.textContent.replace('↗','').trim(),url:link.href,fields:[link.textContent,card.querySelector<HTMLParagraphElement>('.source-purpose').textContent,card.dataset.category||'',card.dataset.country||'',card.dataset.region||'',accessByCard.get(card)||'']};});}
function fuzzy(text,q){let i=0,j=0,score=0,run=0,first=-1;const lower=text.toLowerCase(),needle=q.toLowerCase();for(;i<lower.length&&j<needle.length;i++){if(lower[i]===needle[j]){if(first<0)first=i;score+=(i===0||' ·,;/&-\n'.includes(lower[i-1]))?4:1;run++;score+=run;j++;}else run=0;}return j===needle.length?score+(first===0?6:0):0;}
function paletteScore(entry,q){if(!q)return 1000-entry.index;let best=0;const weights=[3,1,2,2,1,1];entry.fields.forEach((text,w)=>{const s=fuzzy(text,q)*weights[w];if(s>best)best=s;});return best;}
function renderPalette(){const query=paletteInput.value.trim();paletteMatches=paletteItems().map(entry=>({entry,score:paletteScore(entry,query)})).filter(match=>query?match.score>0:true).sort((a,b)=>b.score-a.score).slice(0,8);paletteIndex=Math.min(paletteIndex,Math.max(0,paletteMatches.length-1));const frag=document.createDocumentFragment();paletteMatches.forEach((match,i)=>{const option=document.createElement('a');option.className='palette-option';option.id='palette-option-'+i;option.setAttribute('role','option');option.setAttribute('aria-selected',String(i===paletteIndex));option.href=match.entry.url;option.target='_blank';option.rel='noopener';const title=document.createElement('span');title.className='palette-title';title.textContent=match.entry.title;const meta=document.createElement('span');meta.className='palette-meta';meta.textContent=match.entry.fields[1].trim()+' · '+match.entry.card.dataset.country+' · '+match.entry.card.dataset.category;option.append(title,meta);frag.append(option);});paletteResults.replaceChildren(frag);paletteInput.setAttribute('aria-activedescendant',paletteMatches[paletteIndex]?'palette-option-'+paletteIndex:'');paletteStatus.textContent=paletteMatches.length?t('{n} results').replace('{n}',String(paletteMatches.length)):t('No matching sources');}
function paletteMove(step){if(!paletteMatches.length)return;paletteIndex=(paletteIndex+step+paletteMatches.length)%paletteMatches.length;renderPalette();const active=paletteResults.querySelector<HTMLButtonElement>('[aria-selected=true]');if(active)active.scrollIntoView({block:'nearest'});}
function paletteLaunch(){const match=paletteMatches[paletteIndex];if(!match)return;const url=match.entry.url;paletteDialog.close();window.open(url,'_blank','noopener');}
